const std = @import("std");

const Allocator = std.mem.Allocator;
const ArrayList = std.ArrayList;
const Sha256 = std.crypto.hash.sha2.Sha256;

const MessageRole = enum {
    system,
    user,
    assistant,

    fn asString(self: MessageRole) []const u8 {
        return switch (self) {
            .system => "system",
            .user => "user",
            .assistant => "assistant",
        };
    }

    fn fromString(s: []const u8) ?MessageRole {
        if (std.mem.eql(u8, s, "system")) return .system;
        if (std.mem.eql(u8, s, "user")) return .user;
        if (std.mem.eql(u8, s, "assistant")) return .assistant;
        return null;
    }
};

const Message = struct {
    role: MessageRole,
    content: []u8,
    timestamp_ms: i64,

    fn deinit(self: *Message, allocator: Allocator) void {
        allocator.free(self.content);
        self.* = undefined;
    }
};

const ChatResponse = struct {
    choices: []struct {
        message: struct {
            content: ?[]const u8 = null,
        },
    } = &.{},
};

const ConversationHistory = struct {
    allocator: Allocator,
    filename: []const u8,
    messages: ArrayList(Message),

    pub fn init(allocator: Allocator, filename: []const u8) !ConversationHistory {
        if (filename.len == 0) return error.InvalidFilename;

        var self = ConversationHistory{
            .allocator = allocator,
            .filename = try allocator.dupe(u8, filename),
            .messages = ArrayList(Message).init(allocator),
        };
        errdefer allocator.free(self.filename);

        try self.loadFromFile();
        return self;
    }

    pub fn deinit(self: *ConversationHistory) void {
        self.saveToFile() catch {};
        for (self.messages.items) |*message| {
            message.deinit(self.allocator);
        }
        self.messages.deinit();
        self.allocator.free(self.filename);
    }

    fn loadFromFile(self: *ConversationHistory) !void {
        const file = std.fs.cwd().openFile(self.filename, .{}) catch |err| switch (err) {
            error.FileNotFound => return,
            else => return err,
        };
        defer file.close();

        const stat = try file.stat();
        if (stat.size == 0) return;

        const data = try file.readToEndAlloc(self.allocator, stat.size);
        defer self.allocator.free(data);

        var lines = std.mem.splitScalar(u8, data, '\n');
        while (lines.next()) |line| {
            if (line.len == 0) continue;

            var parts = std.mem.splitScalar(u8, line, '\t');
            const ts_str = parts.next() orelse continue;
            const role_str = parts.next() orelse continue;
            const content_hex = parts.next() orelse continue;
            if (parts.next() != null) continue;

            const role = MessageRole.fromString(role_str) orelse continue;
            const timestamp_ms = std.fmt.parseInt(i64, ts_str, 10) catch continue;
            if (content_hex.len % 2 != 0) continue;

            const content_len = content_hex.len / 2;
            var content = try self.allocator.alloc(u8, content_len);
            errdefer self.allocator.free(content);

            _ = std.fmt.hexToBytes(content, content_hex) catch continue;
            if (!std.unicode.utf8ValidateSlice(content)) {
                self.allocator.free(content);
                continue;
            }

            try self.messages.append(.{
                .role = role,
                .content = content,
                .timestamp_ms = timestamp_ms,
            });
        }
    }

    fn saveToFile(self: *ConversationHistory) !void {
        const file = try std.fs.cwd().createFile(self.filename, .{ .truncate = true });
        defer file.close();

        var writer = file.writer();
        for (self.messages.items) |message| {
            const hex_len = message.content.len * 2;
            const content_hex = try self.allocator.alloc(u8, hex_len);
            defer self.allocator.free(content_hex);

            _ = std.fmt.bufPrint(content_hex, "{s}", .{std.fmt.fmtSliceHexLower(message.content)}) catch unreachable;
            try writer.print("{d}\t{s}\t{s}\n", .{
                message.timestamp_ms,
                message.role.asString(),
                content_hex,
            });
        }
    }

    pub fn appendMessage(self: *ConversationHistory, role: MessageRole, content: []const u8) !void {
        if (!std.unicode.utf8ValidateSlice(content)) return error.InvalidUtf8;
        const owned = try self.allocator.dupe(u8, content);
        errdefer self.allocator.free(owned);

        try self.messages.append(.{
            .role = role,
            .content = owned,
            .timestamp_ms = std.time.milliTimestamp(),
        });
    }

    pub fn buildRecentMessages(self: *ConversationHistory, allocator: Allocator, system_prompt: []const u8, max_history_messages: usize, max_total_bytes: usize) ![]ApiMessage {
        var selected = ArrayList(*const Message).init(allocator);
        defer selected.deinit();

        var total_bytes: usize = system_prompt.len;
        var count: usize = 0;
        var i: usize = self.messages.items.len;
        while (i > 0 and count < max_history_messages) {
            i -= 1;
            const msg = &self.messages.items[i];
            const next_total = total_bytes + msg.content.len;
            if (count > 0 and next_total > max_total_bytes) break;
            try selected.append(msg);
            total_bytes = next_total;
            count += 1;
        }

        std.mem.reverse(*const Message, selected.items);

        var out = try allocator.alloc(ApiMessage, selected.items.len + 1);
        errdefer allocator.free(out);

        out[0] = .{
            .role = "system",
            .content = system_prompt,
        };

        for (selected.items, 0..) |msg, idx| {
            out[idx + 1] = .{
                .role = msg.role.asString(),
                .content = msg.content,
            };
        }

        return out;
    }
};

const ApiMessage = struct {
    role: []const u8,
    content: []const u8,
};

fn writeJsonString(writer: anytype, value: []const u8) !void {
    try writer.writeByte('"');
    for (value) |c| {
        switch (c) {
            '"' => try writer.writeAll("\\\""),
            '\\' => try writer.writeAll("\\\\"),
            '\n' => try writer.writeAll("\\n"),
            '\r' => try writer.writeAll("\\r"),
            '\t' => try writer.writeAll("\\t"),
            else => {
                if (c < 0x20) {
                    try writer.print("\\u{X:0>4}", .{@as(u16, c)});
                } else {
                    try writer.writeByte(c);
                }
            },
        }
    }
    try writer.writeByte('"');
}

fn buildRequestBody(allocator: Allocator, model: []const u8, messages: []const ApiMessage) ![]u8 {
    var list = ArrayList(u8).init(allocator);
    errdefer list.deinit();

    var writer = list.writer();
    try writer.writeAll("{\"model\":");
    try writeJsonString(writer, model);
    try writer.writeAll(",\"messages\":[");

    for (messages, 0..) |msg, i| {
        if (i != 0) try writer.writeByte(',');
        try writer.writeAll("{\"role\":");
        try writeJsonString(writer, msg.role);
        try writer.writeAll(",\"content\":");
        try writeJsonString(writer, msg.content);
        try writer.writeByte('}');
    }

    try writer.writeAll("]}");
    return list.toOwnedSlice();
}

fn parseAssistantContent(allocator: Allocator, resp_body: []const u8) ![]u8 {
    var parsed = try std.json.parseFromSlice(ChatResponse, allocator, resp_body, .{
        .allocate = .alloc_always,
        .ignore_unknown_fields = true,
    });
    defer parsed.deinit();

    if (parsed.value.choices.len == 0) return error.InvalidApiResponse;
    const content = parsed.value.choices[0].message.content orelse return error.InvalidApiResponse;
    return allocator.dupe(u8, content);
}

fn readUserInput(allocator: Allocator, args: []const []const u8) ![]u8 {
    if (args.len >= 2) {
        return std.mem.join(allocator, " ", args[1..]);
    }

    var stdin = std.io.getStdIn().reader();
    return stdin.readAllAlloc(allocator, 64 * 1024);
}

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var args = try std.process.argsAlloc(allocator);
    defer std.process.argsFree(allocator, args);

    const user_input = try readUserInput(allocator, args);
    defer allocator.free(user_input);

    if (user_input.len == 0) return error.EmptyInput;
    if (!std.unicode.utf8ValidateSlice(user_input)) return error.InvalidUtf8;

    var history = try ConversationHistory.init(allocator, "conversation.zigdb");
    defer history.deinit();

    try history.appendMessage(.user, user_input);

    const system_prompt = "You are a helpful assistant.";
    const model_name = "xiaomi/mimo-v2.5-pro";
    const api_key = std.posix.getenv("HPC_API_KEY") orelse return error.MissingApiKey;

    const api_messages = try history.buildRecentMessages(allocator, system_prompt, 24, 32 * 1024);
    defer allocator.free(api_messages);

    const body = try buildRequestBody(allocator, model_name, api_messages);
    defer allocator.free(body);

    var client: std.http.Client = .{ .allocator = allocator };
    defer client.deinit();

    const uri = try std.Uri.parse("");

    const auth_value = try std.fmt.allocPrint(allocator, "Bearer {s}", .{api_key});
    defer allocator.free(auth_value);

    const headers = &[_]std.http.Header{
        .{ .name = "content-type", .value = "application/json" },
        .{ .name = "authorization", .value = auth_value },
    };

    const server_header_buffer = try allocator.alloc(u8, 16 * 1024);
    defer allocator.free(server_header_buffer);

    var req = try client.open(.POST, uri, .{
        .server_header_buffer = server_header_buffer,
        .extra_headers = headers,
    });
    defer req.deinit();

    req.transfer_encoding = .{ .content_length = body.len };
    try req.send();
    try req.writeAll(body);
    try req.finish();
    try req.wait();

    if (req.response.status != .ok) {
        const error_body = try req.reader().readAllAlloc(allocator, 1024 * 1024);
        defer allocator.free(error_body);
        std.debug.print("HTTP {d}: {s}\n", .{@intFromEnum(req.response.status), error_body});
        return error.HttpRequestFailed;
    }

    const resp_body = try req.reader().readAllAlloc(allocator, 1024 * 1024);
    defer allocator.free(resp_body);

    const content = try parseAssistantContent(allocator, resp_body);
    defer allocator.free(content);

    try history.appendMessage(.assistant, content);
    std.debug.print("{s}\n", .{content});
}
